def check_solutions(x, y, z):
    P1 = x**2 + y**2 + z**2
    P2 = x * y**3 + y * z**3 + z * x**3
    return P1 == 3 and P2 == 3

# Test the proposed solutions
solutions_to_check = [(1, 1, 1), (-1, -1, -1)]
for sol in solutions_to_check:
    if check_solutions(sol[0], sol[1], sol[2]):
        print(f"Triple {sol} works.")
    else:
        print(f"Triple {sol} does NOT work.")

